// Des: Spot honeypot links, truncated pages and poisoned records
// Flo: walk tags with a hidden-container stack > link hidden by style, attribute, class, nofollow or parent = trap > page cut short check > required-field check
// I/O: HTML or JSON text (caller) > Link list with trap flag and reason, bool, first bad field name
// ===================================================================
const std = @import("std"); const mem = std.mem; const find = @import("pa-apiz-find.zig"); const urln = @import("ut-urlz-norm.zig"); const vali = @import("sc-reco-vali.zig");
const CF = .{ .maxl = 500, .stkz = 64, .hidn = @as([]const []const u8, &.{ "display:none", "visibility:hidden", "opacity:0;", "opacity:0\"", "font-size:0", "width:0;", "height:0;", "width:0px", "height:0px", "left:-9999", "top:-9999", "text-indent:-9999", "position:absolute;left:-" }), .clas = @as([]const []const u8, &.{ "honeypot", "bot-trap", "hidden-link", "trap-link", "no-bot" }), .voidt = @as([]const []const u8, &.{ "br", "img", "input", "meta", "link", "hr", "area", "base", "col", "embed", "source", "track", "wbr" }) };
pub const Link = struct { urlz: []const u8, trap: bool, why: []const u8 };
fn attrOf(tagz: []const u8, name: []const u8) ?[]const u8 { var buf: [24]u8 = undefined; const pat = std.fmt.bufPrint(&buf, "{s}=", .{name}) catch return null; var from: usize = 0; while (std.ascii.findIgnoreCasePos(tagz, from, pat)) |hit| { from = hit + pat.len; if (hit == 0 or !std.ascii.isWhitespace(tagz[hit - 1])) continue; if (from >= tagz.len) return null; const quot = tagz[from]; if (quot != '"' and quot != '\'') { var endz = from; while (endz < tagz.len and !std.ascii.isWhitespace(tagz[endz]) and tagz[endz] != '>') endz += 1; return tagz[from..endz]; } const endz = mem.findScalarPos(u8, tagz, from + 1, quot) orelse return null; return tagz[from + 1 .. endz]; } return null; }
fn flagOf(tagz: []const u8, name: []const u8) bool { var from: usize = 1; while (std.ascii.findIgnoreCasePos(tagz, from, name)) |hit| { from = hit + name.len; const prev = tagz[hit - 1]; const nxt: u8 = if (hit + name.len < tagz.len) tagz[hit + name.len] else ' '; if (std.ascii.isWhitespace(prev) and (std.ascii.isWhitespace(nxt) or nxt == '>' or nxt == '=' or nxt == '/')) return true; } return false; }
fn hidTag(tagz: []const u8) ?[]const u8 { if (attrOf(tagz, "style")) |sty| { var low: [256]u8 = undefined; var lenz: usize = 0; for (sty) |chr| { if (chr == ' ' or chr == '\t') continue; if (lenz >= low.len) break; low[lenz] = std.ascii.toLower(chr); lenz += 1; } const cmp = low[0..lenz]; var withs: [260]u8 = undefined; @memcpy(withs[0..lenz], cmp); withs[lenz] = ';'; withs[lenz + 1] = '"'; const full = withs[0 .. lenz + 2]; for (CF.hidn) |pat| { if (mem.find(u8, full, pat) != null) return "hidden by style"; } } if (flagOf(tagz, "hidden")) return "hidden attribute"; if (attrOf(tagz, "aria-hidden")) |ah| { if (mem.eql(u8, ah, "true") and (attrOf(tagz, "tabindex") != null)) return "aria-hidden offscreen"; } for ([_][]const u8{ "class", "id" }) |nm| { if (attrOf(tagz, nm)) |val| { for (CF.clas) |pat| { if (std.ascii.findIgnoreCase(val, pat) != null) return "honeypot name"; } } } return null; }
fn isVoid(name: []const u8) bool { for (CF.voidt) |vt| { if (std.ascii.eqlIgnoreCase(vt, name)) return true; } return false; }
pub fn linkFind(aren: std.mem.Allocator, base: []const u8, page: []const u8) ![]Link { const part = try urln.urlSplit(base); const orig = try find.origin(aren, part); var list: std.ArrayList(Link) = .empty; var stk: [CF.stkz][]const u8 = undefined; var hid: [CF.stkz]bool = undefined; var depz: usize = 0; var hidn: usize = 0; var kix: usize = 0; while (kix < page.len and list.items.len < CF.maxl) { const lt = mem.findScalarPos(u8, page, kix, '<') orelse break; const gt = mem.findScalarPos(u8, page, lt, '>') orelse break; kix = gt + 1; const tagz = page[lt .. gt + 1]; if (tagz.len < 3 or tagz[1] == '!' or tagz[1] == '?') continue; if (tagz[1] == '/') { var nm = tagz[2 .. tagz.len - 1]; nm = mem.trim(u8, nm, " \t\r\n"); var jx = depz; while (jx > 0) : (jx -= 1) { if (std.ascii.eqlIgnoreCase(stk[jx - 1], nm)) { while (depz >= jx) { depz -= 1; if (hid[depz]) hidn -= 1; if (depz == 0) break; } break; } } continue; } var ne: usize = 1; while (ne < tagz.len and !std.ascii.isWhitespace(tagz[ne]) and tagz[ne] != '>' and tagz[ne] != '/') ne += 1; const name = tagz[1..ne]; const selfc = tagz[tagz.len - 2] == '/'; const hidr = hidTag(tagz); if (std.ascii.eqlIgnoreCase(name, "a")) { const href = attrOf(tagz, "href") orelse continue; const urlz = (find.joinz(aren, part, orig, href) catch null) orelse continue; const same = urln.urlSplit(urlz) catch continue; if (!std.ascii.eqlIgnoreCase(same.host, part.host) or same.port != part.port) continue; var trap = false; var why: []const u8 = "ok"; if (hidn > 0) { trap = true; why = "inside hidden container"; } else if (hidr) |hr| { trap = true; why = hr; } else if (attrOf(tagz, "rel")) |rl| { if (std.ascii.findIgnoreCase(rl, "nofollow") != null) { trap = true; why = "nofollow"; } } try list.append(aren, .{ .urlz = urlz, .trap = trap, .why = why }); continue; } if (selfc or isVoid(name) or depz >= CF.stkz) continue; stk[depz] = name; hid[depz] = hidr != null; if (hidr != null) hidn += 1; depz += 1; } return list.toOwnedSlice(aren); }
pub fn trunChek(page: []const u8) bool { const trm = mem.trim(u8, page, " \t\r\n"); if (trm.len < 20 or trm[0] != '<') return false; if (std.ascii.findIgnoreCase(trm, "<html") == null) return false; return std.ascii.findIgnoreCase(trm, "</html>") == null; }
pub fn poisChek(aren: std.mem.Allocator, json: []const u8, requ: []const []const u8) !?[]const u8 { const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, json, .{}) catch return "invalid json"; var obj = valu; if (valu == .array) { if (valu.array.items.len == 0) return "empty list"; obj = valu.array.items[0]; } if (obj != .object) return "not an object"; var recs: std.ArrayList(vali.Fiel) = .empty; for (requ) |nm| { const fv = obj.object.get(nm) orelse return nm; const txt: []const u8 = switch (fv) { .string => |sx| sx, .integer => |ix| try std.fmt.allocPrint(aren, "{d}", .{ix}), .float => |fx| try std.fmt.allocPrint(aren, "{d}", .{fx}), .bool => |bx| if (bx) "true" else "false", .null => "null", else => "x" }; try recs.append(aren, .{ .name = nm, .valu = txt }); } return vali.recoChek(recs.items, requ); }
